package com.evolution.analysis.filesystem;
import com.evolution.analysis.acquisition.streaming.*;
import com.evolution.analysis.contract.common.ContentDigest;
import com.evolution.analysis.contract.common.VersionedIdentifier;
import com.evolution.analysis.contract.serialization.CanonicalJson;
import com.evolution.analysis.contract.identity.*;
import com.evolution.analysis.evidence.EvidenceContext;
import com.evolution.analysis.polyglot.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class SemanticPublicationStoreTest {
    @TempDir Path directory;
    record Fixture(StreamingContentStore content,SemanticTables tables,SemanticContextCoordinator.Plan plan,SemanticContextCoordinator.Root result){}
    Map<String,Object> read(Fixture fixture,ContentHandle handle)throws IOException{try(var input=fixture.content().open(handle)){return new TreeMap<>(com.evolution.analysis.graph.GraphJson.object(com.evolution.analysis.graph.GraphJson.read(new String(input.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8),com.evolution.analysis.graph.GraphJson.Limits.defaults())));}}
    ContentHandle put(Fixture fixture,Object value)throws IOException{return fixture.content().put(new ByteArrayInputStream(CanonicalJson.write(value).getBytes(java.nio.charset.StandardCharsets.UTF_8)),()->false);}
    ContentHandle handle(Object raw){var value=com.evolution.analysis.graph.GraphJson.object(raw);return new ContentHandle(new ContentDigest((String)value.get("digest")),((java.math.BigDecimal)value.get("size")).longValueExact());}
    SemanticTables.Table table(Object raw){var value=com.evolution.analysis.graph.GraphJson.object(raw);return new SemanticTables.Table((String)value.get("schema"),SemanticTables.Kind.valueOf((String)value.get("kind")),handle(value.get("content")),((java.math.BigDecimal)value.get("rows")).longValueExact());}
    Fixture fixture()throws Exception{
        var content=new StreamingContentStore(directory.resolve("cas"));var tables=new SemanticTables(content,65536);var inventory=ContentDigest.sha256Utf8("empty sealed inventory");
        var context=EvidenceContext.forSnapshot(SnapshotIdentity.from(RepositoryIdentity.fromCanonicalCoordinate("urn:test:semantic-publication"),inventory));
        var entries=tables.write(SemanticTables.Kind.DOCUMENT,Collections.emptyIterator(),()->false);var report=new PolyglotInventory.Report(inventory,entries,0,0);var coordinator=new SemanticContextCoordinator(content,tables);
        var plan=coordinator.plan(context,report,Collections.emptyIterator(),ContentDigest.sha256Utf8("policy"),()->false);
        var result=coordinator.run(plan,r->Optional.empty(),r->Map.of(),Map.of(),Set.of(),plan::policy,c->{},()->false);return new Fixture(content,tables,plan,result);
    }
    @Test void publicationReopensAndStaleWriterOrCancellationCannotReplaceTheCurrentHead()throws Exception{
        var f=fixture();var store=new SemanticPublicationStore(directory.resolve("heads"),f.content(),f.tables());
        var first=store.commit(f.plan(),f.result(),Optional.empty(),f.plan()::policy,()->false);assertEquals(1,first.revision());assertFalse(f.result().complete());
        var reopened=new SemanticPublicationStore(directory.resolve("heads"),new StreamingContentStore(directory.resolve("cas")),new SemanticTables(new StreamingContentStore(directory.resolve("cas")),65536));
        assertEquals(first,reopened.load(f.plan().identity(),f.plan()::policy,()->false).orElseThrow());
        assertThrows(IOException.class,()->store.commit(f.plan(),f.result(),Optional.empty(),f.plan()::policy,()->false));
        assertThrows(IOException.class,()->store.commit(f.plan(),f.result(),Optional.of(first.document().digest()),f.plan()::policy,()->true));
        assertEquals(first,store.head(f.plan().identity()).orElseThrow());
        assertEquals(first,store.commit(f.plan(),f.result(),Optional.of(first.document().digest()),f.plan()::policy,()->false));
    }
    @Test void revokedPolicyCorruptBytesAndProducerWrittenAuthorityBitsAreRejected()throws Exception{
        var f=fixture();var store=new SemanticPublicationStore(directory.resolve("heads"),f.content(),f.tables());var first=store.commit(f.plan(),f.result(),Optional.empty(),f.plan()::policy,()->false);
        assertThrows(IOException.class,()->store.load(f.plan().identity(),()->ContentDigest.sha256Utf8("revoked"),()->false));
        var forged=new SemanticContextCoordinator.Root(f.result().plan(),f.result().contexts(),f.result().report(),0,0,0,0,0,true,true);
        assertThrows(IOException.class,()->store.commit(f.plan(),forged,Optional.of(first.document().digest()),f.plan()::policy,()->false));
        String hex=f.result().report().digest().value().substring(7);Path blob=directory.resolve("cas/sha256").resolve(hex.substring(0,2)).resolve(hex.substring(2));byte[] bytes=Files.readAllBytes(blob);bytes[0]^=1;Files.write(blob,bytes);
        assertThrows(IOException.class,()->store.load(f.plan().identity(),f.plan()::policy,()->false));assertEquals(first,store.head(f.plan().identity()).orElseThrow());
    }
    @Test void nonemptyHealthyAndMissingContextsSurviveColdPublicationAndSourceLossIsDetected()throws Exception{
        var f=fixture();var source=f.content().put(new ByteArrayInputStream("func run() {}\n".getBytes(java.nio.charset.StandardCharsets.UTF_8)),()->false);
        var resolution=f.content().put(new ByteArrayInputStream("{}".getBytes(java.nio.charset.StandardCharsets.UTF_8)),()->false);
        var emptyDocs=f.plan().inventory().entries();var emptyCensus=f.tables().write(SemanticTables.Kind.CENSUS,Collections.emptyIterator(),()->false);var selections=new ArrayList<SemanticContextCoordinator.Selection>();var outputs=new HashMap<String,SemanticTables.Table>();
        for(String module:List.of("healthy","missing")){
            var provisional=new LanguageSemanticRequest(f.plan().root(),f.plan().inventory().inventory(),"root",module,"main","default","swift","6",emptyDocs,emptyCensus,resolution,new VersionedIdentifier("authored.swift","v1"),ContentDigest.sha256Utf8("tool"),f.plan().policy(),ContentDigest.sha256Utf8("work"));
            var documents=f.tables().write(SemanticTables.Kind.DOCUMENT,List.of(new SemanticTables.Row(SemanticTables.Kind.DOCUMENT,"main.swift",provisional.scope(),Map.of("content",source))).iterator(),()->false);var obligations=new ArrayList<SemanticTables.Row>();var observations=new ArrayList<SemanticTables.Row>();
            for(String category:new TreeSet<>(LanguageProfile.requiredCategories())){
                var row=new SemanticTables.Row(SemanticTables.Kind.CENSUS,category,provisional.scope(),Map.of("document","main.swift","category",category));obligations.add(row);
                observations.add(new SemanticTables.Row(SemanticTables.Kind.OBSERVATION,category,provisional.scope(),Map.of("obligation",row.identity().value(),"status",Set.of("A01","A11","A12").contains(category)?"RESOLVED":"NOT_APPLICABLE","targets",List.of())));
            }
            var request=new LanguageSemanticRequest(provisional.context(),provisional.inventory(),provisional.root(),module,provisional.sourceSet(),provisional.variant(),provisional.language(),provisional.dialect(),documents,f.tables().write(SemanticTables.Kind.CENSUS,obligations.iterator(),()->false),resolution,provisional.provider(),provisional.tool(),provisional.policy(),provisional.workPolicy());selections.add(new SemanticContextCoordinator.Selection(module,request));outputs.put(module,f.tables().write(SemanticTables.Kind.OBSERVATION,observations.iterator(),()->false));
        }
        var coordinator=new SemanticContextCoordinator(f.content(),f.tables());var plan=coordinator.plan(f.plan().root(),f.plan().inventory(),selections.iterator(),f.plan().policy(),()->false);var result=coordinator.run(plan,r->r.module().equals("missing")?Optional.empty():Optional.of((request,cancel)->outputs.get(request.module())),r->Map.of(),Map.of(),Set.of(),plan::policy,c->{},()->false);
        var store=new SemanticPublicationStore(directory.resolve("children"),f.content(),f.tables());var published=store.commit(plan,result,Optional.empty(),plan::policy,()->false);var coldContent=new StreamingContentStore(directory.resolve("cas"));var cold=new SemanticPublicationStore(directory.resolve("children"),coldContent,new SemanticTables(coldContent,65536));assertEquals(published,cold.load(plan.identity(),plan::policy,()->false).orElseThrow());assertEquals(2,published.contexts().rows());assertEquals(1,result.missingProviders());assertEquals(2,result.incomplete());
        var changedChildren=new ArrayList<SemanticTables.Row>();try(var children=f.tables().open(result.contexts(),()->false)){SemanticTables.Row child;while((child=children.next())!=null){if(!child.key().equals("healthy")){changedChildren.add(child);continue;}var receipt=read(f,handle(child.fields().get("receipt")));var changedObservations=new ArrayList<SemanticTables.Row>();try(var observed=f.tables().open(table(receipt.get("observations")),()->false)){SemanticTables.Row observation;while((observation=observed.next())!=null){var fields=new TreeMap<>(observation.fields());fields.put("span",Map.of("path","main.swift","start",0,"end",1,"startLine",99,"startColumn",1,"endLine",99,"endColumn",2));changedObservations.add(new SemanticTables.Row(observation.kind(),observation.key(),observation.scope(),fields));}}receipt.put("observations",f.tables().write(SemanticTables.Kind.OBSERVATION,changedObservations.iterator(),()->false));var fields=new TreeMap<>(child.fields());fields.put("receipt",put(f,receipt));changedChildren.add(new SemanticTables.Row(child.kind(),child.key(),child.scope(),fields));}}
        var changedContexts=f.tables().write(SemanticTables.Kind.CONTEXT,changedChildren.iterator(),()->false);var changedReport=read(f,result.report());changedReport.put("contexts",changedContexts);var forged=new SemanticContextCoordinator.Root(result.plan(),changedContexts,put(f,changedReport),result.selected(),result.processed(),result.failed(),result.missingProviders(),result.incomplete(),false,false);var parent=published.document().digest();assertThrows(IOException.class,()->store.commit(plan,forged,Optional.of(parent),plan::policy,()->false),"A producer label cannot permit fabricated source coordinates through cold publication validation");assertEquals(published,cold.head(plan.identity()).orElseThrow());
        var ledger=new SemanticAnswerLedger(f.content(),f.tables());var history=ledger.append(selections.getFirst().request(),outputs.get("healthy"),Optional.empty(),()->false);var unavailable=coordinator.runWithHistory(plan,r->Optional.empty(),(r,o)->Map.of(),r->r.module().equals("healthy")?Optional.of(history):Optional.empty(),Map.of(),Set.of(),plan::policy,c->{},()->false);published=store.commit(plan,unavailable,Optional.of(published.document().digest()),plan::policy,()->false);assertEquals(published,cold.load(plan.identity(),plan::policy,()->false).orElseThrow());
        var context=cold.queries(plan::policy).contexts(plan.identity(),10,Optional.empty(),()->false).items().getFirst();assertEquals("MISSING_PROVIDER",context.state());assertEquals("1",context.answers().get("historyRevisions"));assertEquals("CAPTURED_PRODUCER_VIEW",context.answers().get("availability"));assertEquals(1,cold.queries(plan::policy).answers(plan.identity(),"healthy","HISTORY",10,Optional.empty(),()->false).items().size());assertEquals(12,cold.queries(plan::policy).answers(plan.identity(),"healthy","CURRENT",50,Optional.empty(),()->false).items().size());assertFalse(cold.queries(plan::policy).summary(plan.identity(),()->false).complete());
        String hex=source.digest().value().substring(7);var file=directory.resolve("cas/sha256").resolve(hex.substring(0,2)).resolve(hex.substring(2));byte[] bytes=Files.readAllBytes(file);bytes[0]^=1;Files.write(file,bytes);assertThrows(IOException.class,()->cold.load(plan.identity(),plan::policy,()->false));assertEquals(published,cold.head(plan.identity()).orElseThrow());
    }
    @Test void rootSummaryCannotInventFailedOrIncompleteChildren()throws Exception{
        var f=fixture();Map<String,Object> report;try(var stream=f.content().open(f.result().report())){report=new TreeMap<>(com.evolution.analysis.graph.GraphJson.object(com.evolution.analysis.graph.GraphJson.read(new String(stream.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8),com.evolution.analysis.graph.GraphJson.Limits.defaults())));}
        report.put("failed",1);report.put("incomplete",1);var forged=f.content().put(new ByteArrayInputStream(CanonicalJson.write(report).getBytes(java.nio.charset.StandardCharsets.UTF_8)),()->false);var result=new SemanticContextCoordinator.Root(f.result().plan(),f.result().contexts(),forged,0,0,1,0,1,false,false);
        var store=new SemanticPublicationStore(directory.resolve("counts"),f.content(),f.tables());assertThrows(IOException.class,()->store.commit(f.plan(),result,Optional.empty(),f.plan()::policy,()->false));assertTrue(store.head(f.plan().identity()).isEmpty());
    }
    @Test void independentRootCensusSurvivesColdReplayAndForgedAccountingCannotPublish()throws Exception{
        var f=fixture();var evidence=f.content().put(new ByteArrayInputStream("authored effective-context frontier".getBytes(java.nio.charset.StandardCharsets.UTF_8)),()->false);var sources=f.tables().write(SemanticTables.Kind.CENSUS,Collections.emptyIterator(),()->false);var contexts=f.tables().write(SemanticTables.Kind.CONTEXT,List.of(new SemanticTables.Row(SemanticTables.Kind.CONTEXT,"unresolved-build-root",f.plan().identity(),Map.of("disposition","UNKNOWN","request",ContentDigest.sha256Utf8("unknown-context"),"reason","DYNAMIC_BUILD_CONTEXT","evidence",evidence))).iterator(),()->false);
        var input=new SemanticRootCensus.Input(sources,contexts,f.plan().inventory().entries(),ContentDigest.sha256Utf8("authored-tool"));var coordinator=new SemanticContextCoordinator(f.content(),f.tables());var supplied=new SemanticContextCoordinator.RootCensus(input,()->new SqliteSemanticCensusIndex(directory.resolve("analysis-"+UUID.randomUUID()+".sqlite"),65536),Optional.empty());var result=coordinator.runWithRootCensus(f.plan(),r->Optional.empty(),(r,o)->Map.of(),r->Optional.empty(),Optional.of(supplied),Map.of(),Set.of(),f.plan()::policy,c->{},()->false);
        var store=new SemanticPublicationStore(directory.resolve("census-publications"),f.content(),f.tables());var publication=store.commit(f.plan(),result,Optional.empty(),f.plan()::policy,()->false);var cold=new SemanticPublicationStore(directory.resolve("census-publications"),f.content(),new SemanticTables(f.content(),65536));assertEquals(publication,cold.load(f.plan().identity(),f.plan()::policy,()->false).orElseThrow());
        var first=cold.queries(f.plan()::policy).rootGaps(f.plan().identity(),1,Optional.empty(),()->false);assertEquals(1,first.items().size());assertTrue(first.continuation().isPresent());var next=cold.queries(f.plan()::policy).rootGaps(f.plan().identity(),1,first.continuation(),()->false);var reasons=Set.of((String)first.items().getFirst().get("reasonCode"),(String)next.items().getFirst().get("reasonCode"));assertEquals(Set.of("ROOT_CONTEXT_ENUMERATION_OPEN","ROOT_SOURCE_CONTEXT_CENSUS_METHOD_UNQUALIFIED"),reasons);
        assertEquals("REPLAYED_PRODUCER_ACCOUNTING",first.summary().accounting().get("availability"));assertEquals("1",first.summary().accounting().get("open"));assertEquals(false,first.summary().accounting().get("structurallyClosed"));assertFalse(first.summary().complete());
        Map<String,Object> report;try(var stream=f.content().open(result.report())){report=new TreeMap<>(com.evolution.analysis.graph.GraphJson.object(com.evolution.analysis.graph.GraphJson.read(new String(stream.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8),com.evolution.analysis.graph.GraphJson.Limits.defaults())));}var census=new TreeMap<>(com.evolution.analysis.graph.GraphJson.object(report.get("rootCensus")));census.put("structurallyClosed",true);report.put("rootCensus",census);var forged=f.content().put(new ByteArrayInputStream(CanonicalJson.write(report).getBytes(java.nio.charset.StandardCharsets.UTF_8)),()->false);var invalid=new SemanticContextCoordinator.Root(result.plan(),result.contexts(),forged,0,0,0,0,0,false,false);assertThrows(IOException.class,()->store.commit(f.plan(),invalid,Optional.of(publication.document().digest()),f.plan()::policy,()->false));assertEquals(publication,store.head(f.plan().identity()).orElseThrow());
    }
}
